const input = $input.first().json;
const brief = $('Initialize Config & Phases').first().json.brief;
const config = $('Initialize Config & Phases').first().json.config;

// Parse concept from Claude response
const responseText = input.message?.content?.[0]?.text || input.content?.[0]?.text || JSON.stringify(input);
const jsonMatch = responseText.match(/\{[\s\S]*\}/);

if (!jsonMatch) {
    throw new Error('Failed to parse concept JSON from Claude response');
}

const concept = JSON.parse(jsonMatch[0]);

// Enrich concept with brief data
concept.intendedDuration = brief.duration;
concept.mixLevel = brief.mixLevel;
concept.generationMode = 'phased';

if (brief.title) concept.title = brief.title;
if (brief.pacingMode) concept.pacingMode = brief.pacingMode;
if (brief.ambiencePrompt && concept.audioIdentity) {
    concept.audioIdentity.ambienceLayer = brief.ambiencePrompt;
}

return {
    json: {
        concept: concept,
        brief: brief,
        config: config,
        phases: brief.phases
    }
};

// Split phases for parallel generation
const input = $input.first().json;
const phases = input.phases;
const concept = input.concept;
const config = input.config;
const brief = input.brief;

// Filter only narration phases (need script generation)
const narrationPhases = phases.filter(p => p.type === 'narration');

// Return each narration phase as separate item for SplitInBatches
return narrationPhases.map(phase => ({
    json: {
        phase: phase,
        phaseIndex: phase.id,
        totalPhases: phases.length,
        concept: concept,
        brief: brief,
        config: config,
        allPhases: phases
    }
}));

