const input = $input.first().json;
const phase = $('Split Narration Phases').first().json.phase;
const concept = $('Split Narration Phases').first().json.concept;
const brief = $('Split Narration Phases').first().json.brief;
const allPhases = $('Split Narration Phases').first().json.allPhases;

// Parse phase content from Claude response
const responseText = input.message?.content?.[0]?.text || input.content?.[0]?.text || JSON.stringify(input);
const jsonMatch = responseText.match(/\{[\s\S]*\}/);

let phaseContent = "Relax and breathe... [pause]";
let wordCount = 0;

if (jsonMatch) {
    try {
        const parsed = JSON.parse(jsonMatch[0]);
        phaseContent = parsed.content || phaseContent;
        wordCount = parsed.wordCount || 0;
    } catch (e) {
        console.log('Parse error, using fallback');
    }
}

return {
    json: {
        phaseId: phase.id,
        phaseType: phase.type,
        content: phaseContent,
        wordCount: wordCount,
        durationSeconds: phase.durationSeconds,
        concept: concept,
        brief: brief
    }
};

// Aggregate all phase scripts into final script object
const items = $input.all();
const firstItem = items[0].json;
const concept = firstItem.concept;
const brief = firstItem.brief;

// Merge all phase contents
const phaseContents = items.map(item => ({
    id: item.json.phaseId,
    type: item.json.phaseType,
    content: item.json.content,
    wordCount: item.json.wordCount,
    durationSeconds: item.json.durationSeconds
}));

// Build complete script
const fullScript = phaseContents.map(p => p.content).join('\n\n');
const totalWords = phaseContents.reduce((sum, p) => sum + p.wordCount, 0);

const generatedScript = {
    title: concept.title,
    category: brief.category,
    duration: brief.duration,
    script: fullScript,
    phases: phaseContents,
    totalWords: totalWords,
    concept: concept,
    mixSettings: { voice: 3.2, music: 0.12, ambience: 0.12 },
    voiceStyle: concept.audioIdentity?.voiceStyle || brief.voiceStyle,
    generationMode: 'phased',
    createdAt: new Date().toISOString()
};

return {
    json: {
        script: generatedScript,
        concept: concept,
        brief: brief
    }
};

