const input = $input.first().json;
const prevData = $('Aggregate Script Phases').first().json;

// Parse asset design from Claude response
const responseText = input.message?.content?.[0]?.text || input.content?.[0]?.text || JSON.stringify(input);
const jsonMatch = responseText.match(/\{[\s\S]*\}/);

let assetDesign = {
    coverPrompt: `Dreamy ethereal artwork for "${prevData.concept.title}" - ${prevData.brief.category} audio experience, 8k resolution, cinematic lighting`,
    musicPrompt: 'NEW: Gentle ambient piano with soft pads, 60 BPM, cinematic quality, warm analogue texture',
    ambiencePrompt: 'High fidelity rain sounds with distant thunder, binaural recording quality, seamless loop',
    backingCategory: 'soundscape',
    backingTitle: prevData.concept.title + ' Ambience'
};

if (jsonMatch) {
    try {
        const parsed = JSON.parse(jsonMatch[0]);
        assetDesign = { ...assetDesign, ...parsed };
    } catch (e) {
        console.log('Asset design parse error, using defaults');
    }
}

return {
    json: {
        assetDesign: assetDesign,
        script: prevData.script,
        concept: prevData.concept,
        brief: prevData.brief
    }
};

// Prepare voice generation items (one per narration phase)
const input = $input.first().json;
const script = input.script;
const voiceStyle = script.voiceStyle || 'soft_female';

// Default voice IDs from VoiceService.ts
const DEFAULT_VOICES = {
    soft_female: 'mZ3kbJNnKRWI4YzJXA9j',
    soft_male: 'NOpBlnGInO9m6vDvFkFC',
    neutral: 'mZ3kbJNnKRWI4YzJXA9j'
};

const voiceId = DEFAULT_VOICES[voiceStyle] || DEFAULT_VOICES.soft_female;

// Filter narration phases with content
const narrationPhases = script.phases.filter(p => p.type === 'narration' && p.content);

return narrationPhases.map(phase => {
    // Clean text for TTS (from index.ts generatePhasedVoice)
    const cleanText = phase.content
        .replace(/\[breathe.*?\]/gi, ' ... ')
        .replace(/\[.*?\]/g, (m) => m.includes('pause') ? ' ... ' : '')
        .replace(/\(.*?\)/g, '').trim();

    return {
        json: {
            phaseId: phase.id,
            text: cleanText,
            voiceId: voiceId,
            voiceStyle: voiceStyle,
            script: script,
            assetDesign: input.assetDesign,
            concept: input.concept,
            brief: input.brief
        }
    };
});

// Merge all generated assets including stitched voice
const stitchedVoice = $('Stitch Voice Files (CLI)').first().binary;
const musicData = $('Generate Music (Stable Audio)').first();
const ambienceData = $('Generate Ambience (Stable Audio)').first();
const cover1x1 = $('Generate Cover Art 1:1 (DALL-E 3)').first().json;
const cover16x9 = $('Generate Cover Art 16:9 (DALL-E 3)').first().json;
const cover9x16 = $('Generate Cover Art 9:16 (DALL-E 3)').first().json;
const scriptData = $('Prepare Voice Generation').first().json.script;
const concept = $('Prepare Voice Generation').first().json.concept;

// Build slug
const slug = scriptData.title.toLowerCase().replace(/[^a-z0-9]/g, '-');
const datePrefix = new Date().toISOString().split('T')[0];
const storageRoot = `${datePrefix}/${slug}`;

return {
    json: {
        storyData: {
            title: scriptData.title,
            slug: slug,
            category: scriptData.category,
            duration: scriptData.duration * 60,
            script_text: scriptData.script,
            audio_phases: scriptData.phases,
            tags: concept.tags || [],
            is_published: false
        },
        assetUrls: {
            cover_1x1_url: cover1x1.data?.[0]?.url || null,
            cover_16x9_url: cover16x9.data?.[0]?.url || null,
            cover_9x16_url: cover9x16.data?.[0]?.url || null
        },
        storageRoot: storageRoot,
        script: scriptData,
        concept: concept
    },
    binary: {
        voice: stitchedVoice,
        music: musicData.binary?.data || null,
        ambience: ambienceData.binary?.data || null
    }
};

// Final summary
const input = $input.first().json;
const mergeData = $('Merge All Assets').first().json;

const storyId = input.id || 'generated-' + Date.now();

return {
    json: {
        success: true,
        storyId: storyId,
        title: mergeData.storyData.title,
        slug: mergeData.storyData.slug,
        category: mergeData.storyData.category,
        duration: mergeData.storyData.duration,
        phasesGenerated: mergeData.script.phases.length,
        totalWords: mergeData.script.totalWords,
        assetsGenerated: {
            voiceFiles: mergeData.voiceFiles.length,
            musicGenerated: true,
            ambienceGenerated: true,
            coverVariants: 3
        },
        message: `✅ Story "${mergeData.storyData.title}" generated successfully!`
    }
};
